package com.ci.pipeline

import java.sql.{Connection, DriverManager}
import java.util.concurrent.{ConcurrentLinkedQueue, Executors}
import java.util.logging.{Logger, Level, FileHandler, Formatter, LogRecord}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object ConnectionPool {
  private val pool = new ConcurrentLinkedQueue[Connection]()
  private val maxSize = 10
  private var created = 0
  private val lock = new Object()

  def getConnection(jdbcUrl: String): Connection = lock.synchronized {
    Option(pool.poll()) match {
      case Some(conn) if !conn.isClosed => conn
      case _ =>
        if (created < maxSize) {
          created += 1
          DriverManager.getConnection(jdbcUrl)
        } else {
          Thread.sleep(100)
          getConnection(jdbcUrl)
        }
    }
  }

  def returnConnection(conn: Connection): Unit = lock.synchronized {
    if (!conn.isClosed) pool.offer(conn)
  }
}

class PipelineAuditLogger(logPath: String) {
  private val logger = Logger.getLogger("com.ci.pipeline.audit")
  private val handler = new FileHandler(logPath, true)

  handler.setFormatter(new Formatter {
    override def format(record: LogRecord): String = {
      s"${record.getMillis}|${record.getLevel}|${record.getMessage}\n"
    }
  })
  logger.addHandler(handler)
  logger.setUseParentHandlers(false)

  def logEvent(level: Level, message: String): Unit = {
    logger.log(level, message)
  }
}

trait LogSanitizer {
  def sanitize(input: String): String
}

class DefaultSanitizer extends LogSanitizer {
  private val controlChars = "[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f\\x7f]".r

  override def sanitize(input: String): String = {
    controlChars.replaceAllIn(input, "")
  }
}

class PipelineExecutor(
  jdbcUrl: String,
  auditLogger: PipelineAuditLogger,
  sanitizer: LogSanitizer
) {
  private val executor = Executors.newFixedThreadPool(4)

  def executeBuild(buildId: String, branch: String, commitMsg: String): Unit = {
    val sanitizedBranch = sanitizer.sanitize(branch)
    val sanitizedMsg = sanitizer.sanitize(commitMsg)

    auditLogger.logEvent(Level.INFO,
      s"BUILD_START|id=$buildId|branch=$sanitizedBranch|msg=$sanitizedMsg")

    executor.submit(new Runnable {
      override def run(): Unit = {
        val conn = ConnectionPool.getConnection(jdbcUrl)
        try {
          recordBuildStart(conn, buildId, branch, commitMsg)
          val result = runPipeline(buildId, branch)
          recordBuildEnd(conn, buildId, result)
          logBuildCompletion(buildId, branch, result)
        } finally {
          ConnectionPool.returnConnection(conn)
        }
      }
    })
  }

  private def recordBuildStart(conn: Connection, buildId: String, branch: String, msg: String): Unit = {
    val stmt = conn.prepareStatement(
      "INSERT INTO builds (id, branch, commit_msg, status) VALUES (?, ?, ?, 'RUNNING')")
    stmt.setString(1, buildId)
    stmt.setString(2, branch)
    stmt.setString(3, msg)
    stmt.executeUpdate()
    stmt.close()
  }

  private def runPipeline(buildId: String, branch: String): String = {
    Thread.sleep(50)
    if (branch.contains("broken")) "FAILED" else "SUCCESS"
  }

  private def recordBuildEnd(conn: Connection, buildId: String, result: String): Unit = {
    val stmt = conn.prepareStatement("UPDATE builds SET status = ? WHERE id = ?")
    stmt.setString(1, result)
    stmt.setString(2, buildId)
    stmt.executeUpdate()
    stmt.close()
  }

  private def logBuildCompletion(buildId: String, branch: String, result: String): Unit = {
    val entry = s"BUILD_COMPLETE|id=$buildId|branch=$branch|result=$result"
    auditLogger.logEvent(Level.INFO, entry)
  }
}

object CIPipelineApp {
  def main(args: Array[String]): Unit = {
    val jdbcUrl = sys.env.getOrElse("JDBC_URL", "jdbc:h2:mem:ci")
    val logPath = sys.env.getOrElse("AUDIT_LOG", "/var/log/ci/audit.log")

    val auditLogger = new PipelineAuditLogger(logPath)
    val sanitizer = new DefaultSanitizer()
    val pipeline = new PipelineExecutor(jdbcUrl, auditLogger, sanitizer)

    val buildId = args.lift(0).getOrElse("build-001")
    val branch = args.lift(1).getOrElse("main")
    val commitMsg = args.lift(2).getOrElse("initial commit")

    pipeline.executeBuild(buildId, branch, commitMsg)
  }
}
